import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"状态压缩 DP","description":"","frontmatter":{"title":"状态压缩 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bitmask-dp.md","filePath":"cs/bitmask-dp.md","lastUpdated":1789023840000}'),h={name:"cs/bitmask-dp.md"};function m(_,a,P,D,u,E){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="状态压缩-dp" tabindex="-1">状态压缩 DP <a class="header-anchor" href="#状态压缩-dp" aria-label="Permalink to &quot;状态压缩 DP&quot;">​</a></h1><div class="epigraph"><p>子集或网格一行用比特掩码当状态下标；$2^n$ 个子集上转移，常 $O(3^n)$ 或 $O(2^n\\mathrm{poly})$。</p><footer>—— 据 Held and Karp, 1962 的子集 DP；CLRS 第 15 章整理</footer></div><p>上一课<a href="/cs/probability-dp">概率与期望 DP</a>把状态方程写在一般 \\(s\\) 上。主干<a href="/cs/dynamic-programming">动态规划</a>已给最优子结构。缺口是 \\(s\\subseteq\\{1..n\\}\\) 用整数掩码。哈密顿课的 Held–Karp 已是实例；本课把状压收成技法：旅行商、子集和、棋盘铺砖一行。不重写期望方程。后课树形 DP 换树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\le 20\\) 时 \\(2^n\\) 可存。转移：枚举子集、子集的子集（\\(O(3^n)\\)：对每位 0/不选/选在子集）、或按位 SOS DP（\\(O(n2^n)\\)）点名。铺砖：第 \\(i\\) 行掩码与第 \\(i-1\\) 行兼容则转移。</p><p>缺口是掩码，不是再证 NPC。精确 TSP 已讲，本课强调通用接口。</p><h3 id="不是把-硬压" tabindex="-1">不是把 \\(n=40\\) 硬压 <a class="header-anchor" href="#不是把-硬压" aria-label="Permalink to &quot;不是把 $n=40$ 硬压&quot;">​</a></h3><p>\\(2^{40}\\) 内存爆炸。要折半、meet-in-the-middle 或换算法。不要「状压万能」。</p><p><span class="marginnote">Held–Karp 子集。SOS DP 是高维前缀。后课插头 DP 是网格边界轮廓，比一行掩码更细。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编码占用/奇偶/颜色到比特。预处理合法掩码列表。转移循环 <code>for s</code> <code>for t subset s</code> 或滚动数组两行。</p>',11)),(e(),s(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E5%AD%90%E9%9B%86%20S%22%5D%20--%3E%20MASK%5B%22%E6%AF%94%E7%89%B9%E6%8E%A9%E7%A0%81%22%5D%0A%20%20MASK%20--%3E%20DP%5B%22dp%5Bs%5D%20%E6%88%96%20dp%5Bi%5D%5Bs%5D%22%5D%0A%20%20DP%20--%3E%20TR%5B%22%E6%9E%9A%E4%B8%BE%E5%AD%90%E6%8E%A9%E7%A0%81%20%2F%20%E5%85%BC%E5%AE%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>位运算 <code>__builtin_ctz</code> 枚举。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>状态空间指数但 \\(n\\) 小则多项式于 \\(2^n\\)。与生成函数：子集卷积可用 Walsh/NTT，本课朴素 \\(3^n\\) 先会。与线性基：都是比特，一个优化一个 DP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 SOS 恒等式。不写量子。后课默认：\\(n\\le 20\\) 子集问题优先状压。下一课树形 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩码下标 = 子集；转移枚举子掩码或兼容行。</li><li>\\(O(3^n)\\)、\\(O(n2^n)\\) 是常见界。</li><li>\\(n\\) 稍大即不可用。</li><li>出处：Held and Karp, 1962；CLRS 第 15 章。</li></ul>',7))])}const S=n(h,[["render",m]]);export{f as __pageData,S as default};
